async (page) => {
  const api = page.request;
  const base = 'http://localhost:3000';
  const email = `probe-${Date.now()}@example.test`;
  const reg = await api.post(`${base}/api/Users/`, { data: { email, password: 'Passw0rd!tc01', passwordRepeat: 'Passw0rd!tc01', securityQuestion: { id: 1, question: 'Your eldest siblings middle name?' }, securityAnswer: 'x' } });
  const regBody = await reg.text();
  const login = await api.post(`${base}/rest/user/login`, { data: { email, password: 'Passw0rd!tc01' } });
  const lb = await login.json();
  const token = lb.authentication.token;
  const h = { Authorization: `Bearer ${token}` };
  const addr = await api.post(`${base}/api/Addresss/`, { headers: h, data: { fullName: 'Test Customer', mobileNum: 501234567, zipCode: '01001', streetAddress: '1 Khreshchatyk Street', city: 'Kyiv', state: 'Kyiv', country: 'Ukraine' } });
  const card = await api.post(`${base}/api/Cards/`, { headers: h, data: { fullName: 'Test Customer', cardNum: 4111111111111111, expMonth: 12, expYear: 2090 } });
  const cardB = await card.json();
  const wallet = await api.put(`${base}/rest/wallet/balance`, { headers: h, data: { paymentId: String(cardB.data.id), balance: 5 } });
  const w = await api.get(`${base}/rest/wallet/balance`, { headers: h });
  return { reg: reg.status(), regBody: regBody.slice(0, 200), login: login.status(), addr: addr.status(), card: card.status(), cardBody: JSON.stringify(cardB).slice(0,200), wallet: wallet.status(), walletBody: await wallet.text(), walletGet: await w.text() };
}

