import type { Page } from '@playwright/test';

export class LoginPage {
  constructor(private readonly page: Page) {}

  async goto(): Promise<void> {
    await this.page.goto('/#/login');
  }

  get heading() {
    return this.page.getByRole('heading', { name: 'Login', exact: true });
  }

  get emailField() {
    return this.page.getByRole('textbox', { name: 'Text field for the login email' });
  }

  get passwordField() {
    return this.page.getByRole('textbox', { name: 'Text field for the login password' });
  }

  get loginButton() {
    return this.page.getByRole('button', { name: 'Login', exact: true });
  }

  get invalidCredentialsError() {
    return this.page.getByText('Invalid email or password.');
  }

  async fill(email: string, password: string): Promise<void> {
    await this.emailField.fill(email);
    await this.passwordField.fill(password);
  }

  async login(email: string, password: string): Promise<void> {
    await this.fill(email, password);
    await this.loginButton.click();
  }
}

