await (async (page) => {
  const base = 'http://localhost:3000';
  const email = `probe6-${Date.now()}@example.test`;
  const pw = 'Passw0rd!tc01';
  const api = page.request;
  await api.post(`${base}/api/Users/`, { data: { email, password: pw, passwordRepeat: pw, securityQuestion: { id: 1, question: 'q' }, securityAnswer: 'x' } });
  const lb = await (await api.post(`${base}/rest/user/login`, { data: { email, password: pw } })).json();
  const h = { Authorization: `Bearer ${lb.authentication.token}` };
  await api.post(`${base}/api/Addresss/`, { headers: h, data: { fullName: 'Test Customer', mobileNum: 501234567, zipCode: '01001', streetAddress: '1 Khreshchatyk Street', city: 'Kyiv', state: 'Kyiv', country: 'Ukraine' } });
  const card = await (await api.post(`${base}/api/Cards/`, { headers: h, data: { fullName: 'Test Customer', cardNum: 4111111111111111, expMonth: 12, expYear: 2090 } })).json();
  await api.put(`${base}/rest/wallet/balance`, { headers: h, data: { paymentId: String(card.data.id), balance: 5 } });
  await page.context().addCookies([{ name: 'cookieconsent_status', value: 'dismiss', url: base }]);
  await page.goto(`${base}/#/login`);
  await page.getByRole('textbox', { name: 'Text field for the login email' }).fill(email);
  await page.getByRole('textbox', { name: 'Text field for the login password' }).fill(pw);
  await page.getByRole('button', { name: 'Login', exact: true }).click();
  await page.waitForURL(/#\/search/);
  await page.waitForTimeout(1500);
  const art = page.locator('article').filter({ has: page.getByText('Eggfruit Juice (500ml)', { exact: true }) });
  await art.getByRole('button', { name: 'Add to Basket' }).click();
  await page.waitForTimeout(1200);
  await art.getByRole('button', { name: 'Add to Basket' }).click();
  await page.waitForTimeout(1500);
  const out = {};
  out.counter = await page.locator('button', { hasText: 'Your Basket' }).textContent();
  await page.getByRole('button', { name: 'Show the shopping cart' }).click();
  await page.waitForURL(/#\/basket/);
  await page.waitForTimeout(1200);
  const b = (await page.locator('body').ariaSnapshot()).split('\n');
  out.basket = b.slice(14, 60).join('\n');
  await page.getByRole('button', { name: 'Checkout' }).click();
  await page.waitForTimeout(1500);
  out.addressUrl = page.url();
  const a = (await page.locator('body').ariaSnapshot()).split('\n');
  out.address = a.slice(14, 60).join('\n');
  return out;
})(page);
```
