import { expect, type Page } from '@playwright/test';
import { totalPrice } from '../helpers/money';

/** Closes the cookie banner if it is shown. The cookie alone does not hide it in this build. */
export async function dismissCookieBanner(page: Page): Promise<void> {
  const dismiss = page.getByRole('button', { name: 'dismiss cookie message' });
  if (await dismiss.isVisible()) {
    await dismiss.click();
  }
}

/** The top bar that is shown on every page of the shop. */
export class TopBar {
  constructor(private readonly page: Page) {}

  get accountButton() {
    return this.page.getByRole('button', { name: 'Show/hide account menu' });
  }

  get basketButton() {
    return this.page.locator('button', { hasText: 'Your Basket' });
  }

  get accountMenu() {
    return this.page.getByRole('menu').first();
  }

  async openAccountMenu(): Promise<void> {
    await this.accountButton.click();
    await expect(this.accountMenu).toBeVisible();
  }

  async closeAccountMenu(): Promise<void> {
    await this.page.keyboard.press('Escape');
    await expect(this.accountMenu).toBeHidden();
  }

  /** Account menu, then `Orders & Payment`, then the item, for example `Order History`. */
  async openOrdersAndPaymentItem(item: string): Promise<void> {
    await this.openAccountMenu();
    await this.accountMenu.getByRole('menuitem', { name: /Orders (&|and) Payment/ }).click();
    await expect(this.page.getByRole('menuitem', { name: new RegExp(`^${item}`) })).toBeVisible();
    await this.page.getByRole('menuitem', { name: new RegExp(`^${item}`) }).click();
  }

  async openBasket(): Promise<void> {
    await this.basketButton.click();
    await expect(this.page).toHaveURL(/#\/basket/);
  }

  async expectBasketCounter(count: number): Promise<void> {
    await expect(this.basketButton).toHaveText(new RegExp(`Your Basket\\s*${count}\\s*$`));
  }
}

/** The product list `/#/search`. */
export class ProductListPage {
  constructor(private readonly page: Page) {}

  async goto(): Promise<void> {
    await this.page.goto('/#/search');
    await expect(this.page).toHaveURL(/#\/search/);
    await dismissCookieBanner(this.page);
  }

  /** Opens the product list filtered by a search term. Only the first page of the list is shown without it. */
  async search(term: string): Promise<void> {
    await this.page.goto(`/#/search?q=${encodeURIComponent(term)}`);
    await expect(this.page).toHaveURL(/#\/search/);
    await dismissCookieBanner(this.page);
  }

  productTile(name: string) {
    return this.page.locator('article').filter({ has: this.page.getByText(name, { exact: true }) });
  }

  /** Clicks `Add to Basket` on the product without checking the result. */
  async clickAddToBasket(name: string): Promise<void> {
    await this.productTile(name).getByRole('button', { name: 'Add to Basket' }).click();
  }

  /** Clicks `Add to Basket` and waits for the message that the product was placed into the basket. */
  async addToBasket(name: string): Promise<void> {
    await this.clickAddToBasket(name);
    await this.expectMessage(`Placed ${name} into basket.`);
  }

  async expectProductTile(name: string, price: string): Promise<void> {
    const tile = this.productTile(name);
    await expect(tile).toBeVisible();
    await expect(tile).toContainText(price);
    await expect(tile.getByRole('button', { name: 'Add to Basket' })).toBeVisible();
  }

  async expectMessage(text: string): Promise<void> {
    await expect(this.page.getByText(text).first()).toBeVisible();
  }
}

/** The basket `/#/basket`. */
export class BasketPage {
  constructor(private readonly page: Page) {}

  row(name: string) {
    return this.page.getByRole('row').filter({ hasText: name });
  }

  /** The quantity cell is the third cell: minus button, quantity, plus button. */
  private quantityCell(name: string) {
    return this.row(name).getByRole('cell').nth(2);
  }

  increase(name: string) {
    return this.quantityCell(name).getByRole('button').last();
  }

  decrease(name: string) {
    return this.quantityCell(name).getByRole('button').first();
  }

  /** The trash button is in the last cell of the row. */
  remove(name: string) {
    return this.row(name).getByRole('cell').last().getByRole('button');
  }

  get checkoutButton() {
    return this.page.locator('button', { hasText: 'Checkout' });
  }

  async expectRow(name: string, quantity: number): Promise<void> {
    await expect(this.row(name)).toBeVisible();
    await expect(this.quantityCell(name).getByText(String(quantity), { exact: true })).toBeVisible();
  }

  async expectNoRow(name: string): Promise<void> {
    await expect(this.row(name)).toHaveCount(0);
  }

  async expectTotal(total: string): Promise<void> {
    await expect(this.page.getByText(totalPrice(total))).toBeVisible();
  }
}

