import { expect, type Page } from '@playwright/test';
import { escapeRegExp, price } from '../helpers/money';
import { DELIVERY, SAVED_ADDRESS } from '../helpers/test-data';

/** The masked number of the saved card, see test-cases/README.md. */
const SAVED_CARD_MASKED = '************1111';

/** The page `Select an address` of the checkout. */
export class AddressPage {
  constructor(private readonly page: Page) {}

  async expectOpen(): Promise<void> {
    await expect(this.page).toHaveURL(/#\/address\/select/);
    await expect(this.page.getByRole('heading', { name: 'Select an address' })).toBeVisible();
  }

  savedAddress() {
    return this.page.getByRole('row').filter({ hasText: SAVED_ADDRESS.address });
  }

  async selectSavedAddress(): Promise<void> {
    await this.savedAddress().getByRole('radio').click();
  }

  async continue(): Promise<void> {
    await this.page.locator('button', { hasText: 'Continue' }).click();
  }
}

/** The page `Choose a delivery speed` of the checkout. */
export class DeliveryPage {
  constructor(private readonly page: Page) {}

  async expectOpen(): Promise<void> {
    await expect(this.page).toHaveURL(/#\/delivery-method/);
    await expect(this.page.getByRole('heading', { name: 'Choose a delivery speed' })).toBeVisible();
  }

  option(name: string) {
    return this.page.getByRole('row').filter({ hasText: name });
  }

  async expectOptions(): Promise<void> {
    await expect(this.option(DELIVERY.oneDay.name)).toContainText(price(DELIVERY.oneDay.price));
    await expect(this.option(DELIVERY.fast.name)).toContainText(price(DELIVERY.fast.price));
    await expect(this.option(DELIVERY.standard.name)).toContainText(price(DELIVERY.standard.price));
  }

  async select(name: string): Promise<void> {
    await this.option(name).getByRole('radio').click();
  }

  async continue(): Promise<void> {
    await this.page.locator('button', { hasText: 'Continue' }).click();
  }
}

/** The page `My Payment Options` of the checkout. */
export class PaymentPage {
  constructor(private readonly page: Page) {}

  async expectOpen(): Promise<void> {
    await expect(this.page).toHaveURL(/#\/payment\/shop/);
    await expect(this.page.getByRole('heading', { name: 'My Payment Options' })).toBeVisible();
  }

  get couponPanel() {
    return this.page.getByRole('button', { name: /^Add a coupon/ });
  }

  get couponField() {
    return this.page.getByRole('textbox', { name: /coupon/i });
  }

  get redeemButton() {
    return this.page.locator('button', { hasText: 'Redeem' });
  }

  async redeemCoupon(code: string): Promise<void> {
    await this.couponPanel.click();
    await this.couponField.fill(code);
    await this.redeemButton.click();
  }

  savedCard() {
    return this.page.getByRole('row').filter({ hasText: SAVED_CARD_MASKED });
  }

  async selectSavedCard(): Promise<void> {
    await this.savedCard().getByRole('radio').click();
  }

  async continue(): Promise<void> {
    await this.page.locator('button', { hasText: 'Continue' }).click();
  }

  walletPayButton(total: string) {
    return this.page.getByRole('button', { name: `Pay ${total}` });
  }
}

/** The page `Order Summary` of the checkout. */
export class OrderSummaryPage {
  constructor(private readonly page: Page) {}

  async expectOpen(): Promise<void> {
    await expect(this.page).toHaveURL(/#\/order-summary/);
    await expect(this.page.getByText('Order Summary', { exact: true })).toBeVisible();
  }

  /** A line of the summary table, for example `Items`. The footer row is not a line. */
  line(label: string) {
    return this.page.locator('tr.mat-row').filter({ has: this.page.getByRole('cell', { name: label, exact: true }) });
  }

  async expectLine(label: string, value: string): Promise<void> {
    await expect(this.line(label)).toContainText(price(value));
  }

  async expectTotals(items: string, delivery: string, promotion: string, total: string): Promise<void> {
    await this.expectLine('Items', items);
    await this.expectLine('Delivery', delivery);
    await this.expectLine('Promotion', promotion);
    await this.expectLine('Total Price', total);
  }

  async placeOrder(): Promise<void> {
    await this.page.locator('button', { hasText: 'Place your order and pay' }).click();
  }
}

/** Totals on the confirmation page. There the labels and values sit in one nested table. */
export class ConfirmationTotals {
  constructor(private readonly page: Page) {}

  async expectTotals(items: string, delivery: string, promotion: string, total: string): Promise<void> {
    const values = [items, delivery, promotion, total].map(escapeRegExp).join('\\s*');
    // The outer row is the one that contains the nested table with the labels.
    const totals = this.page.locator('tr', { has: this.page.locator('table') });
    await expect(totals).toContainText(new RegExp(`Items\\s*Delivery\\s*Promotion\\s*Total Price\\s*${values}`));
  }
}

/** The confirmation page `/#/order-completion/<order ID>`. */
export class OrderCompletionPage {
  constructor(private readonly page: Page) {}

  async expectOpen(): Promise<string> {
    await expect(this.page).toHaveURL(/#\/order-completion\/.+/);
    await expect(this.page.getByText('Thank you for your purchase!')).toBeVisible();
    const match = /#\/order-completion\/([^/?#]+)/.exec(this.page.url());
    if (!match) {
      throw new Error(`No order ID in URL: ${this.page.url()}`);
    }
    return decodeURIComponent(match[1]);
  }
}

